#include "upload/archive.h"

#include "core/util.h"

#include <ctype.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

static uint16_t le16(const unsigned char *p)
{
    return (uint16_t)p[0] | ((uint16_t)p[1] << 8);
}

static uint32_t le32(const unsigned char *p)
{
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

/* True when [offset, offset + len) lies inside size bytes, without computing a sum that can wrap on 32-bit size_t. */
static bool in_bounds(size_t offset, size_t len, size_t size)
{
    return offset <= size && len <= size - offset;
}

static bool read_file(Arena *arena, const char *path, unsigned char **out_data, size_t *out_size)
{
    FILE *f = fopen(path, "rb");
    if (!f) return false;
    long len = fseek(f, 0, SEEK_END) == 0 ? ftell(f) : -1;
    if (len < 0 || len > VD_UPLOAD_MAX_BYTES || fseek(f, 0, SEEK_SET) != 0) {
        fclose(f);
        return false;
    }
    unsigned char *data = arena_alloc(arena, (size_t)len);
    if (!data) {
        fclose(f);
        return false;
    }
    size_t read_len = fread(data, 1, (size_t)len, f);
    fclose(f);
    if (read_len != (size_t)len) {
        return false;
    }
    *out_data = data;
    *out_size = read_len;
    return true;
}

static bool safe_zip_path(const char *name)
{
    if (!name || name[0] == '\0' || name[0] == '/') return false;
    if (strstr(name, "..")) return false;
    if (strchr(name, '\\')) return false;
    return true;
}

static bool is_macos_metadata_path(const char *name)
{
    if (strncmp(name, "__MACOSX/", 9) == 0) return true;
    const char *base = strrchr(name, '/');
    base = base ? base + 1 : name;
    return strcmp(base, ".DS_Store") == 0 || strncmp(base, "._", 2) == 0;
}

static bool top_level_name(const char *entry_name, char *out, size_t out_size)
{
    const char *slash = strchr(entry_name, '/');
    size_t len = slash ? (size_t)(slash - entry_name) : strlen(entry_name);
    if (len == 0 || len + 1 > out_size) return false;
    memcpy(out, entry_name, len);
    out[len] = '\0';
    return true;
}

static bool write_stored(const unsigned char *data, size_t size, const char *out_path)
{
    if (!vd_mkdir_parent(out_path)) return false;
    FILE *f = fopen(out_path, "wb");
    if (!f) return false;
    bool ok = fwrite(data, 1, size, f) == size;
    fclose(f);
    return ok;
}

static bool write_deflated(const unsigned char *data, size_t compressed_size, size_t uncompressed_size,
                           const char *out_path)
{
    if (!vd_mkdir_parent(out_path)) return false;
    FILE *f = fopen(out_path, "wb");
    if (!f) return false;

    z_stream stream;
    memset(&stream, 0, sizeof(stream));
    stream.next_in = (Bytef *)data;
    stream.avail_in = (uInt)compressed_size;

    unsigned char chunk[16 * 1024];
    bool ok = inflateInit2(&stream, -MAX_WBITS) == Z_OK;
    int ret = Z_OK;
    while (ok && ret != Z_STREAM_END) {
        stream.next_out = chunk;
        stream.avail_out = sizeof(chunk);
        ret = inflate(&stream, Z_NO_FLUSH);
        size_t produced = sizeof(chunk) - stream.avail_out;
        ok = (ret == Z_OK || ret == Z_STREAM_END) && stream.total_out <= uncompressed_size &&
             fwrite(chunk, 1, produced, f) == produced;
    }
    ok = ok && stream.total_out == uncompressed_size;
    inflateEnd(&stream);
    fclose(f);
    return ok;
}

bool upload_archive_extract(Arena *arena, const char *zip_path, VdArchiveExtractResult *result, char *error,
                            size_t error_size)
{
    memset(result, 0, sizeof(*result));

    unsigned char *zip = NULL;
    size_t zip_size = 0;
    if (!read_file(arena, zip_path, &zip, &zip_size)) {
        vd_set_error(error, error_size, "Archive is missing or exceeds upload size limit.");
        return false;
    }
    if (zip_size < 22) {
        vd_set_error(error, error_size, "Archive is not a supported zip file.");
        return false;
    }

    size_t eocd_pos = (size_t)-1;
    size_t search_start = zip_size > 66000 ? zip_size - 66000 : 0;
    for (size_t i = zip_size - 22; i >= search_start && i < zip_size; i--) {
        if (le32(zip + i) == 0x06054b50) {
            eocd_pos = i;
            break;
        }
        if (i == 0) break;
    }
    if (eocd_pos == (size_t)-1) {
        vd_set_error(error, error_size, "Archive is not a supported zip file.");
        return false;
    }

    unsigned int entry_count = le16(zip + eocd_pos + 10);
    uint32_t central_size = le32(zip + eocd_pos + 12);
    uint32_t central_offset = le32(zip + eocd_pos + 16);
    if (entry_count == 0 || entry_count > VD_UPLOAD_MAX_ENTRIES || !in_bounds(central_offset, central_size, zip_size)) {
        vd_set_error(error, error_size, "Archive entry count or directory is invalid.");
        return false;
    }

    package_library_clear_staging();

    char top_name[VD_PACKAGE_NAME_MAX] = "";
    size_t total_unpacked = 0;
    size_t pos = central_offset;
    for (unsigned int i = 0; i < entry_count; i++) {
        if (pos + 46 > zip_size || le32(zip + pos) != 0x02014b50) {
            vd_set_error(error, error_size, "Archive central directory is invalid.");
            return false;
        }

        uint16_t method = le16(zip + pos + 10);
        uint32_t compressed_size = le32(zip + pos + 20);
        uint32_t uncompressed_size = le32(zip + pos + 24);
        uint16_t name_len = le16(zip + pos + 28);
        uint16_t extra_len = le16(zip + pos + 30);
        uint16_t comment_len = le16(zip + pos + 32);
        uint32_t local_offset = le32(zip + pos + 42);
        if (pos + 46 + name_len + extra_len + comment_len > zip_size || name_len >= VD_PATH_MAX) {
            vd_set_error(error, error_size, "Archive entry metadata is invalid.");
            return false;
        }

        char entry_name[VD_PATH_MAX];
        memcpy(entry_name, zip + pos + 46, name_len);
        entry_name[name_len] = '\0';
        pos += 46 + name_len + extra_len + comment_len;

        if (is_macos_metadata_path(entry_name)) continue;

        if (!safe_zip_path(entry_name)) {
            vd_set_error(error, error_size, "Archive contains an unsafe path.");
            return false;
        }

        char entry_top[VD_PACKAGE_NAME_MAX];
        if (!top_level_name(entry_name, entry_top, sizeof(entry_top)) || !vd_has_suffix(entry_top, ".vdapp")) {
            vd_set_error(error, error_size, "Archive must contain exactly one top-level .vdapp directory.");
            return false;
        }
        if (top_name[0] == '\0') {
            snprintf(top_name, sizeof(top_name), "%s", entry_top);
        } else if (strcmp(top_name, entry_top) != 0) {
            vd_set_error(error, error_size, "Archive contains more than one top-level entry.");
            return false;
        }

        bool is_directory = entry_name[strlen(entry_name) - 1] == '/';
        if (is_directory) continue;

        if (uncompressed_size > VD_UPLOAD_MAX_UNPACKED_BYTES - total_unpacked ||
            !in_bounds(local_offset, 30, zip_size) || le32(zip + local_offset) != 0x04034b50) {
            vd_set_error(error, error_size, "Archive exceeds unpacked size limit or has invalid local data.");
            return false;
        }
        total_unpacked += uncompressed_size;

        uint16_t local_name_len = le16(zip + local_offset + 26);
        uint16_t local_extra_len = le16(zip + local_offset + 28);
        size_t data_offset = local_offset + 30 + local_name_len + local_extra_len;
        if (!in_bounds(data_offset, compressed_size, zip_size)) {
            vd_set_error(error, error_size, "Archive entry data is invalid.");
            return false;
        }

        char out_path[VD_PATH_MAX];
        vd_join_path(out_path, sizeof(out_path), package_library_staging_root(), entry_name);
        bool ok = false;
        if (method == 0) {
            ok = compressed_size == uncompressed_size && write_stored(zip + data_offset, uncompressed_size, out_path);
        } else if (method == 8) {
            ok = write_deflated(zip + data_offset, compressed_size, uncompressed_size, out_path);
        }
        if (!ok) {
            vd_set_error(error, error_size, "Archive contains an unsupported or invalid compressed entry.");
            return false;
        }
    }

    if (top_name[0] == '\0') {
        vd_set_error(error, error_size, "Archive did not contain a Deck App Package Directory.");
        return false;
    }

    snprintf(result->package_name, sizeof(result->package_name), "%s", top_name);
    vd_join_path(result->package_path, sizeof(result->package_path), package_library_staging_root(), top_name);
    return true;
}
